begin;

do $$ begin
 if to_regclass('public.tyre_shop_bills') is not null or to_regclass('public.voucher_tyre_entries') is not null then raise exception 'TYRE_PHASE_2: conflicting deployment objects'; end if;
 if to_regprocedure('public.save_vehicle_tyre_entry(uuid,uuid,date,public.tyre_source_type,uuid,public.tyre_work_type,text,bigint,text,jsonb)') is null or to_regprocedure('public.ut_sync_voucher_cashbook(text)') is null then raise exception 'TYRE_PHASE_2: required deployed contracts are missing'; end if;
 if exists(select 1 from public.tyre_vehicle_entries e left join public.tyre_shops s on s.id=e.tyre_shop_id left join public.vehicles v on v.id=e.vehicle_id where e.source_type='external_shop' and (e.total_amount<=0 or s.id is null or s.shop_type<>'external_supplier' or s.adda_id<>e.adda_id or v.id is null or v.adda_id<>e.adda_id)) then raise exception 'TYRE_PHASE_2: unsafe authoritative Tyre source'; end if;
 if exists(select 1 from public.cashbook_entries where reference_type='tyre_shop_payment') then raise exception 'TYRE_PHASE_2: unexplained pre-deployment Cashbook rows'; end if;
end $$;

create table public.tyre_shop_bills(
 id uuid primary key default gen_random_uuid(), adda_id uuid not null references public.addas(id) on delete restrict,
 tyre_shop_id uuid not null references public.tyre_shops(id) on delete restrict,
 source_type text not null default 'tyre_vehicle_entry' check(source_type='tyre_vehicle_entry'),
 tyre_vehicle_entry_id uuid not null references public.tyre_vehicle_entries(id) on delete cascade,
 bill_date date not null,bill_no text,amount numeric(14,2) not null check(amount>0),
 paid_amount numeric(14,2) not null default 0 check(paid_amount>=0),remaining_amount numeric(14,2) not null check(remaining_amount>=0),
 payment_status text not null default 'unpaid' check(payment_status in('unpaid','partial','paid')),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tyre_vehicle_entry_id)
);
create index tyre_shop_bills_shop_date_idx on public.tyre_shop_bills(tyre_shop_id,bill_date,id);
create table public.tyre_shop_payments(
 id bigint generated by default as identity primary key,tyre_shop_id uuid not null references public.tyre_shops(id) on delete restrict,
 payment_date date not null,amount numeric(14,2) not null check(amount>=0),payment_method text,reference_no text,remarks text,created_at timestamptz not null default now(),
 advance_used numeric(14,2) not null default 0 check(advance_used>=0),payment_now numeric(14,2) not null default 0 check(payment_now>=0),opening_applied numeric(14,2) not null default 0 check(opening_applied>=0),advance_created numeric(14,2) not null default 0 check(advance_created>=0),available_advance_before numeric(14,2) not null default 0 check(available_advance_before>=0),current_payable_before numeric(14,2) not null default 0 check(current_payable_before>=0),remaining_payable numeric(14,2) not null default 0 check(remaining_payable>=0),remaining_advance numeric(14,2) not null default 0 check(remaining_advance>=0),settlement_status text not null default 'paid' check(settlement_status in('payable','advance','paid')),accounting_version smallint not null default 1
);
create index tyre_shop_payments_shop_date_idx on public.tyre_shop_payments(tyre_shop_id,payment_date,created_at,id);
create table public.tyre_shop_payment_allocations(
 id uuid primary key default gen_random_uuid(),payment_id bigint not null references public.tyre_shop_payments(id) on delete cascade,
 tyre_shop_bill_id uuid not null references public.tyre_shop_bills(id) on delete cascade,amount numeric(14,2) not null check(amount>0),created_at timestamptz not null default now(),unique(payment_id,tyre_shop_bill_id)
);
create index tyre_shop_payment_allocations_bill_idx on public.tyre_shop_payment_allocations(tyre_shop_bill_id);
create unique index cashbook_entries_tyre_shop_payment_uidx on public.cashbook_entries(reference_type,reference_id) where reference_type='tyre_shop_payment' and reference_id is not null;

alter table public.tyre_shop_bills enable row level security;alter table public.tyre_shop_payments enable row level security;alter table public.tyre_shop_payment_allocations enable row level security;
create policy tyre_shop_bills_select on public.tyre_shop_bills for select to authenticated using((select public.is_super_admin()) or adda_id=(select public.current_user_adda_id()));
create policy tyre_shop_payments_select on public.tyre_shop_payments for select to authenticated using(exists(select 1 from public.tyre_shops s where s.id=tyre_shop_id and ((select public.is_super_admin()) or s.adda_id=(select public.current_user_adda_id()))));
create policy tyre_shop_allocations_select on public.tyre_shop_payment_allocations for select to authenticated using(exists(select 1 from public.tyre_shop_payments payment_row join public.tyre_shops s on s.id=payment_row.tyre_shop_id where payment_row.id=payment_id and ((select public.is_super_admin()) or s.adda_id=(select public.current_user_adda_id()))));
revoke all on public.tyre_shop_bills,public.tyre_shop_payments,public.tyre_shop_payment_allocations from public,anon,authenticated;grant select on public.tyre_shop_bills,public.tyre_shop_payments,public.tyre_shop_payment_allocations to authenticated;

create function public.rebuild_tyre_shop_accounting(p_tyre_shop_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare supplier_row record;payment_row record;bill_row record;v_opening numeric;v_opening_due numeric;v_advance numeric;v_payable numeric;v_advance_used numeric;v_settlement numeric;v_apply numeric;v_created numeric;
begin
 select * into supplier_row from public.tyre_shops where id=p_tyre_shop_id and shop_type='external_supplier' for update;if not found then raise exception 'TYRE_SHOP_NOT_FOUND';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tyre_shop_id::text,0));perform set_config('ut.tyre_shop_sync','on',true);perform set_config('ut.cashbook_sync','on',true);
 delete from public.tyre_shop_payment_allocations allocation using public.tyre_shop_payments payment_source where allocation.payment_id=payment_source.id and payment_source.tyre_shop_id=p_tyre_shop_id;
 update public.tyre_shop_bills set paid_amount=0,remaining_amount=amount,payment_status='unpaid',updated_at=now() where tyre_shop_id=p_tyre_shop_id;
 v_opening:=coalesce(supplier_row.opening_balance,0);v_opening_due:=greatest(v_opening,0);v_advance:=greatest(-v_opening,0);
 for payment_row in select * from public.tyre_shop_payments where tyre_shop_id=p_tyre_shop_id order by payment_date,created_at,id for update loop
  select v_opening_due+coalesce(sum(remaining_amount),0) into v_payable from public.tyre_shop_bills where tyre_shop_id=p_tyre_shop_id;
  v_advance_used:=least(coalesce(payment_row.advance_used,0),v_advance,v_payable);v_settlement:=v_advance_used+coalesce(payment_row.payment_now,0);v_advance:=v_advance-v_advance_used;v_created:=0;
  v_apply:=least(v_settlement,v_opening_due);v_opening_due:=v_opening_due-v_apply;v_settlement:=v_settlement-v_apply;
  for bill_row in select * from public.tyre_shop_bills where tyre_shop_id=p_tyre_shop_id and remaining_amount>0 order by bill_date,created_at,id for update loop
   exit when v_settlement<=0;v_apply:=least(v_settlement,bill_row.remaining_amount);
   insert into public.tyre_shop_payment_allocations(payment_id,tyre_shop_bill_id,amount) values(payment_row.id,bill_row.id,v_apply);
   update public.tyre_shop_bills set paid_amount=paid_amount+v_apply,remaining_amount=remaining_amount-v_apply,payment_status=case when remaining_amount-v_apply=0 then 'paid' else 'partial' end,updated_at=now() where id=bill_row.id;v_settlement:=v_settlement-v_apply;
  end loop;
  if v_settlement>0 then v_created:=v_settlement;v_advance:=v_advance+v_settlement;end if;
  select v_opening_due+coalesce(sum(remaining_amount),0) into v_payable from public.tyre_shop_bills where tyre_shop_id=p_tyre_shop_id;
  update public.tyre_shop_payments set advance_used=v_advance_used,amount=v_advance_used+coalesce(payment_now,0),opening_applied=least(v_advance_used+coalesce(payment_now,0),greatest(v_opening,0)),advance_created=v_created,available_advance_before=v_advance+v_advance_used-v_created,current_payable_before=v_payable+(v_advance_used+coalesce(payment_now,0)-v_created),remaining_payable=v_payable,remaining_advance=v_advance,settlement_status=case when v_payable>0 then 'payable' when v_advance>0 then 'advance' else 'paid' end,accounting_version=1 where id=payment_row.id;
  if coalesce(payment_row.payment_now,0)>0 then insert into public.cashbook_entries(entry_date,entry_type,person_type,person_name,payment_method,amount,description,reference_type,reference_id) values(payment_row.payment_date,'Cash Out','Other',supplier_row.shop_name,coalesce(nullif(payment_row.payment_method,''),'Cash'),payment_row.payment_now,'Tyre shop payment - '||supplier_row.shop_name,'tyre_shop_payment',payment_row.id::text) on conflict(reference_type,reference_id) where reference_type='tyre_shop_payment' and reference_id is not null do update set entry_date=excluded.entry_date,entry_type=excluded.entry_type,person_type=excluded.person_type,person_name=excluded.person_name,payment_method=excluded.payment_method,amount=excluded.amount,description=excluded.description;
  else delete from public.cashbook_entries where reference_type='tyre_shop_payment' and reference_id=payment_row.id::text;end if;
 end loop;
end $$;

create function public.save_tyre_shop_payment(p_payment_id bigint,p_tyre_shop_id uuid,p_payment_date date,p_advance_used numeric,p_payment_now numeric,p_payment_method text,p_reference_no text,p_remarks text) returns bigint language plpgsql security definer set search_path=public,pg_temp as $$
declare v_id bigint;v_adda uuid;v_advance numeric:=coalesce(p_advance_used,0);v_now numeric:=coalesce(p_payment_now,0);
begin
 if auth.uid() is null or public.current_user_role() not in('super_admin','adda_admin','operator') then raise exception 'AUTHORIZATION_FAILED';end if;
 select adda_id into v_adda from public.tyre_shops where id=p_tyre_shop_id and shop_type='external_supplier';if v_adda is null then raise exception 'TYRE_SHOP_NOT_FOUND';end if;
 if not public.is_super_admin() and v_adda is distinct from public.current_user_adda_id() then raise exception 'TENANT_MISMATCH';end if;
 if p_payment_date is null or v_advance<0 or v_now<0 or v_advance+v_now<=0 then raise exception 'INVALID_PAYMENT';end if;perform set_config('ut.tyre_shop_sync','on',true);
 if p_payment_id is null then insert into public.tyre_shop_payments(tyre_shop_id,payment_date,amount,advance_used,payment_now,payment_method,reference_no,remarks) values(p_tyre_shop_id,p_payment_date,v_advance+v_now,v_advance,v_now,nullif(btrim(p_payment_method),''),nullif(btrim(p_reference_no),''),nullif(btrim(p_remarks),'')) returning id into v_id;
 else select id into v_id from public.tyre_shop_payments where id=p_payment_id and tyre_shop_id=p_tyre_shop_id for update;if v_id is null then raise exception 'PAYMENT_NOT_FOUND_OR_SUPPLIER_CHANGE';end if;update public.tyre_shop_payments set payment_date=p_payment_date,amount=v_advance+v_now,advance_used=v_advance,payment_now=v_now,payment_method=nullif(btrim(p_payment_method),''),reference_no=nullif(btrim(p_reference_no),''),remarks=nullif(btrim(p_remarks),'') where id=v_id;end if;
 perform public.rebuild_tyre_shop_accounting(p_tyre_shop_id);return v_id;
end $$;
create function public.delete_tyre_shop_payment(p_payment_id bigint) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare v_shop uuid;v_adda uuid;begin select payment_row.tyre_shop_id,shop.adda_id into v_shop,v_adda from public.tyre_shop_payments payment_row join public.tyre_shops shop on shop.id=payment_row.tyre_shop_id where payment_row.id=p_payment_id for update;if v_shop is null then raise exception 'PAYMENT_NOT_FOUND';end if;if auth.uid() is null or public.current_user_role() not in('super_admin','adda_admin','operator') or(not public.is_super_admin() and v_adda is distinct from public.current_user_adda_id()) then raise exception 'AUTHORIZATION_FAILED';end if;perform set_config('ut.tyre_shop_sync','on',true);perform set_config('ut.cashbook_sync','on',true);delete from public.cashbook_entries where reference_type='tyre_shop_payment' and reference_id=p_payment_id::text;delete from public.tyre_shop_payments where id=p_payment_id;perform public.rebuild_tyre_shop_accounting(v_shop);end $$;

create function public.ut_protect_tyre_shop_accounting() returns trigger language plpgsql set search_path=public,pg_temp as $$ begin if coalesce(current_setting('ut.tyre_shop_sync',true),'')<>'on' then raise exception 'Tyre Shop accounting rows must be changed through approved RPCs';end if;return case when tg_op='DELETE' then old else new end;end $$;
create trigger tyre_shop_bills_protect before insert or update or delete on public.tyre_shop_bills for each row execute function public.ut_protect_tyre_shop_accounting();create trigger tyre_shop_payments_protect before insert or update or delete on public.tyre_shop_payments for each row execute function public.ut_protect_tyre_shop_accounting();create trigger tyre_shop_allocations_protect before insert or update or delete on public.tyre_shop_payment_allocations for each row execute function public.ut_protect_tyre_shop_accounting();
create function public.ut_sync_tyre_shop_source_bill() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_old_shop uuid;v_new_shop uuid;
begin perform set_config('ut.tyre_shop_sync','on',true);
 if tg_op<>'INSERT' and old.source_type='external_shop' then v_old_shop:=old.tyre_shop_id;delete from public.tyre_shop_bills where tyre_vehicle_entry_id=old.id;end if;
 if tg_op<>'DELETE' and new.source_type='external_shop' and new.total_amount>0 then v_new_shop:=new.tyre_shop_id;insert into public.tyre_shop_bills(adda_id,tyre_shop_id,tyre_vehicle_entry_id,bill_date,bill_no,amount,remaining_amount) values(new.adda_id,new.tyre_shop_id,new.id,new.entry_date,new.bill_no,new.total_amount,new.total_amount);end if;
 if v_old_shop is not null then perform public.rebuild_tyre_shop_accounting(v_old_shop);end if;if v_new_shop is not null and v_new_shop is distinct from v_old_shop then perform public.rebuild_tyre_shop_accounting(v_new_shop);end if;return case when tg_op='DELETE' then old else new end;
end $$;
create trigger tyre_vehicle_entries_shop_bill after insert or update or delete on public.tyre_vehicle_entries for each row execute function public.ut_sync_tyre_shop_source_bill();
create function public.ut_protect_tyre_shop_cashbook() returns trigger language plpgsql set search_path=public,pg_temp as $$ begin if(case when tg_op='DELETE' then old.reference_type='tyre_shop_payment' else new.reference_type='tyre_shop_payment' or(tg_op='UPDATE' and old.reference_type='tyre_shop_payment') end) and coalesce(current_setting('ut.cashbook_sync',true),'')<>'on' then raise exception 'Tyre Shop Cashbook entries must be changed from Tyre Shop Account';end if;return case when tg_op='DELETE' then old else new end;end $$;
create trigger cashbook_entries_protect_tyre_shop before insert or update or delete on public.cashbook_entries for each row execute function public.ut_protect_tyre_shop_cashbook();

do $$ begin perform set_config('ut.tyre_shop_sync','on',true);insert into public.tyre_shop_bills(adda_id,tyre_shop_id,tyre_vehicle_entry_id,bill_date,bill_no,amount,remaining_amount) select e.adda_id,e.tyre_shop_id,e.id,e.entry_date,e.bill_no,e.total_amount,e.total_amount from public.tyre_vehicle_entries e join public.tyre_shops s on s.id=e.tyre_shop_id and s.shop_type='external_supplier' where e.source_type='external_shop' and e.total_amount>0 on conflict do nothing;end $$;

create table public.voucher_tyre_entries(id uuid primary key default gen_random_uuid(),voucher_id bigint not null references public.expenses(id) on delete cascade,tyre_vehicle_entry_id uuid not null references public.tyre_vehicle_entries(id) on delete restrict,created_at timestamptz not null default now(),unique(tyre_vehicle_entry_id),unique(voucher_id,tyre_vehicle_entry_id));
create index voucher_tyre_entries_voucher_idx on public.voucher_tyre_entries(voucher_id);alter table public.voucher_tyre_entries enable row level security;revoke all on public.voucher_tyre_entries from public,anon,authenticated;grant select on public.voucher_tyre_entries to authenticated;
create policy voucher_tyre_entries_select on public.voucher_tyre_entries for select to authenticated using(exists(select 1 from public.expenses e join public.loadings l on l.id=e.loading_id left join public.bookings b on b.id=l.booking_id join public.vehicles vehicle on vehicle.id=l.vehicle_id join public.addas context_adda on context_adda.id=case when l.booking_id is null then vehicle.adda_id else b.adda_id end join public.tyre_vehicle_entries tyre_entry on tyre_entry.id=voucher_tyre_entries.tyre_vehicle_entry_id where e.id=voucher_tyre_entries.voucher_id and(l.booking_id is null or b.id is not null) and tyre_entry.vehicle_id=l.vehicle_id and tyre_entry.adda_id=context_adda.id and((select public.is_super_admin()) or context_adda.id=(select public.current_user_adda_id()))));
create function public.sync_voucher_tyre_entries(p_voucher_id bigint,p_tyre_vehicle_entry_ids uuid[]) returns void language plpgsql security definer set search_path='' as $$
declare voucher_record record;requested_count integer;valid_count integer;requested_total numeric;tyre_item_count integer;tyre_item_total numeric;
begin
 if auth.uid() is null or public.current_user_role() not in('super_admin','adda_admin','operator') then raise exception using errcode='42501',message='Unauthorized Voucher Tyre linkage';end if;
 select e.id,context_adda.id adda_id,l.vehicle_id into voucher_record from public.expenses e join public.loadings l on l.id=e.loading_id left join public.bookings b on b.id=l.booking_id join public.vehicles vehicle on vehicle.id=l.vehicle_id join public.addas context_adda on context_adda.id=case when l.booking_id is null then vehicle.adda_id else b.adda_id end where e.id=p_voucher_id and(l.booking_id is null or b.id is not null) for update of e;
 if not found then raise exception 'Voucher or tenant context not found';end if;if not public.is_super_admin() and voucher_record.adda_id is distinct from public.current_user_adda_id() then raise exception using errcode='42501',message='Voucher belongs to another Adda';end if;
 select count(*) into requested_count from(select distinct unnest(coalesce(p_tyre_vehicle_entry_ids,array[]::uuid[]))) ids;
 select count(*) into valid_count from public.tyre_vehicle_entries e where e.id=any(coalesce(p_tyre_vehicle_entry_ids,array[]::uuid[])) and e.adda_id=voucher_record.adda_id and e.vehicle_id=voucher_record.vehicle_id and e.total_amount>0 and not exists(select 1 from public.voucher_tyre_entries link where link.tyre_vehicle_entry_id=e.id and link.voucher_id<>p_voucher_id);
 if requested_count<>coalesce(array_length(p_tyre_vehicle_entry_ids,1),0) or valid_count<>requested_count then raise exception using errcode='23514',message='One or more Tyre Entries are duplicate, unavailable, invalid, or outside the Voucher vehicle/Adda';end if;
 select coalesce(sum(total_amount),0) into requested_total from public.tyre_vehicle_entries where id=any(coalesce(p_tyre_vehicle_entry_ids,array[]::uuid[]));select count(*),coalesce(sum(amount),0) into tyre_item_count,tyre_item_total from public.expense_items where expense_id=p_voucher_id and expense_type='Tyre';
 if(requested_count=0 and tyre_item_count<>0)or(requested_count>0 and(tyre_item_count<>1 or tyre_item_total<>requested_total))then raise exception using errcode='23514',message='Tyre Voucher item must exactly match selected persisted Tyre totals';end if;
 delete from public.voucher_tyre_entries where voucher_id=p_voucher_id and not(tyre_vehicle_entry_id=any(coalesce(p_tyre_vehicle_entry_ids,array[]::uuid[])));insert into public.voucher_tyre_entries(voucher_id,tyre_vehicle_entry_id) select p_voucher_id,id from unnest(coalesce(p_tyre_vehicle_entry_ids,array[]::uuid[])) id on conflict(voucher_id,tyre_vehicle_entry_id)do nothing;
end $$;

create or replace function public.ut_sync_voucher_cashbook(p_voucher_id text) returns void language plpgsql security definer set search_path='' as $$
declare voucher_record record;voucher_total numeric;begin perform pg_catalog.set_config('ut.cashbook_sync','on',true);select e.id,e.expense_no,coalesce(e.start_date,e.expense_date) accounting_date,e.loading_id,l.vehicle_id,l.driver_id into voucher_record from public.expenses e join public.loadings l on l.id=e.loading_id where e.id::text=p_voucher_id;if not found then delete from public.cashbook_entries where reference_type='voucher' and reference_id=p_voucher_id;return;end if;
 select coalesce(sum(i.amount),0) into voucher_total from public.expense_items i where i.expense_id=voucher_record.id and not((i.expense_type='Workshop' and exists(select 1 from public.voucher_workshop_entries v where v.voucher_id=i.expense_id))or(i.expense_type='Oil / Lubricants' and exists(select 1 from public.voucher_oil_entries v where v.voucher_id=i.expense_id))or(i.expense_type='Tyre' and exists(select 1 from public.voucher_tyre_entries v where v.voucher_id=i.expense_id)));
 if voucher_total::text in('NaN','Infinity','-Infinity')or voucher_total<0 then raise exception 'Voucher total cannot be negative';end if;if voucher_total=0 then delete from public.cashbook_entries where reference_type='voucher' and reference_id=voucher_record.id::text;return;end if;
 update public.cashbook_entries set entry_date=voucher_record.accounting_date,entry_type='Cash Out',person_type='Other',person_name='Voucher',vehicle_id=voucher_record.vehicle_id,driver_id=voucher_record.driver_id,loading_id=voucher_record.loading_id,payment_method='Cash',amount=voucher_total,description='Voucher - '||coalesce(nullif(btrim(voucher_record.expense_no),''),voucher_record.id::text),reference_type='voucher',reference_id=voucher_record.id::text where reference_type='voucher' and reference_id=voucher_record.id::text;if not found then insert into public.cashbook_entries(entry_date,entry_type,person_type,person_name,vehicle_id,driver_id,loading_id,payment_method,amount,description,reference_type,reference_id)values(voucher_record.accounting_date,'Cash Out','Other','Voucher',voucher_record.vehicle_id,voucher_record.driver_id,voucher_record.loading_id,'Cash',voucher_total,'Voucher - '||coalesce(nullif(btrim(voucher_record.expense_no),''),voucher_record.id::text),'voucher',voucher_record.id::text);end if;end $$;
create function public.ut_sync_voucher_tyre_link_cashbook() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='DELETE' then perform public.ut_sync_voucher_cashbook(old.voucher_id::text);return old;end if;perform public.ut_sync_voucher_cashbook(new.voucher_id::text);return new;end $$;
create trigger voucher_tyre_entries_sync_cashbook after insert or delete on public.voucher_tyre_entries for each row execute function public.ut_sync_voucher_tyre_link_cashbook();

revoke all on function public.rebuild_tyre_shop_accounting(uuid),public.save_tyre_shop_payment(bigint,uuid,date,numeric,numeric,text,text,text),public.delete_tyre_shop_payment(bigint),public.ut_protect_tyre_shop_accounting(),public.ut_sync_tyre_shop_source_bill(),public.ut_protect_tyre_shop_cashbook(),public.sync_voucher_tyre_entries(bigint,uuid[]),public.ut_sync_voucher_tyre_link_cashbook() from public,anon,authenticated;
grant execute on function public.save_tyre_shop_payment(bigint,uuid,date,numeric,numeric,text,text,text),public.delete_tyre_shop_payment(bigint),public.sync_voucher_tyre_entries(bigint,uuid[]) to authenticated;
commit;
